    // unchanged) as a single Halide Func so that all per-step computation
    // is done inside Halide. We still perform the time loop in C++, which
    // is the legal way to handle the loop-carried dependency over t.
    Func A_prev_bc("A_prev_bc");   // Boundary-conditioned previous time-step
    Func seidel_step("seidel_step");

    // Wrap A_prev in a clamp-to-edge boundary condition so that all
    // 3x3 stencil accesses are in-bounds even at the edges. This
    // does NOT change the semantics for interior points, and we will
    // explicitly preserve boundary values below.
    A_prev_bc(x, y) = BoundaryConditions::repeat_edge(A_prev_param)(x, y);

    // Denominator as an Expr of num_t
    Expr denom = cast<num_t>(Expr(SCALAR_VAL(9.0)));

    // Sum of the 3x3 neighborhood, reading from the boundary-conditioned input.
    Expr neighborhood_sum =
        A_prev_bc(x - 1, y - 1) +
        A_prev_bc(x - 1, y)     +
        A_prev_bc(x - 1, y + 1) +
        A_prev_bc(x,     y - 1) +
        A_prev_bc(x,     y)     +
        A_prev_bc(x,     y + 1) +
        A_prev_bc(x + 1, y - 1) +
        A_prev_bc(x + 1, y)     +
        A_prev_bc(x + 1, y + 1);

