    // Make the loop over rows (i) parallel, and vectorize over columns (j).
    // We split j into outer/inner so that we can use wide vectors while still
    // handling arbitrary problem sizes.
    init_A
        .compute_root()
        .split(j, jo, ji, vec_width * 8)  // 8 vectors per tile in x
        .vectorize(ji, vec_width)         // SIMD across columns
        .parallel(i);                     // parallelize across rows

    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size and time steps
    int n = N;
    int tsteps = TSTEPS;

    // Buffers for current and next time-step values.
    // We treat dimension 0 as column (j), dimension 1 as row (i),
    // so that C's A[i][j] maps to A(j, i).
    Buffer<num_t, 2> A_cur(n, n);
    Buffer<num_t, 2> A_next(n, n);

    // Initialize A_cur
    init_array(n, A_cur);

    // ImageParam to represent the "previous" time-step array in Halide
    ImageParam A_prev_param(type_of<num_t>(), 2, "A_prev");

    // Vars for spatial indices
    Var x("x"), y("y");

    // One time-step of the 2D Seidel/Jacobi-like update, expressed in Halide.
    //
    // Original C update (for interior points 1..n-2):
    //
    // A[i][j] = (A[i-1][j-1] + A[i-1][j] + A[i-1][j+1]
    //            + A[i][j-1] + A[i][j] + A[i][j+1]
    //            + A[i+1][j-1] + A[i+1][j] + A[i+1][j+1]) / 9.0;
    //
    // Mapping to Halide coordinates: i -> y, j -> x, A[i][j] -> A_prev_param(x, y).
    Func seidel_step("seidel_step");

    // Use Expr() so that we don't accidentally rely on C++-side casts;
    // this keeps everything in Halide's type system.
    Expr denom = cast<num_t>(Expr(SCALAR_VAL(9.0)));

    seidel_step(x, y) =
        (A_prev_param(x - 1, y - 1) +
         A_prev_param(x - 1, y) +
         A_prev_param(x - 1, y + 1) +
         A_prev_param(x,     y - 1) +
         A_prev_param(x,     y) +
         A_prev_param(x,     y + 1) +
         A_prev_param(x + 1, y - 1) +
         A_prev_param(x + 1, y) +
         A_prev_param(x + 1, y + 1)) / denom;

    // ------------------------------------------------------------------
    // Schedule for the stencil kernel
    //
    // We exploit the fact that x is the innermost, contiguous dimension:
    //   - vectorize along x,
    //   - tile in x and y to improve cache locality,
    //   - parallelize over tiles in y.
    //
    // We only ever realize seidel_step over the interior [1..n-2]^2,
    // so all accesses A_prev_param(x±1, y±1) stay in-bounds without
    // explicit boundary conditions. Bounds inference will infer that
    // A_prev_param needs [0..n-1]^2, which matches our buffers.
    // ------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tunable tile sizes: number of vectors per tile in x, and rows per tile in y.
    const int vectors_per_tile_x = 8;  // more vectors per tile improves locality
    const int tile_x = vec_width * vectors_per_tile_x;
    const int tile_y = 32;             // 32 rows per tile; good for L1/L2 reuse

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    seidel_step
        .compute_root()
        // Tile the iteration space into tile_x by tile_y blocks.
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
        // Vectorize across xi (contiguous dimension).
        .vectorize(xi, vec_width)
        // Parallelize across tiles in the y direction. With 32 cores, this
        // should expose plenty of parallelism even for modest n.
        .parallel(yo);

    // JIT-compile the per-time-step pipeline once
    seidel_step.compile_jit(target);

    // Start timing
    auto start = std::chrono::high_resolution_clock::now();

    // Double-buffering over time steps.
    // We keep pointers to the "current" and "next" buffers and swap each step.
    Buffer<num_t, 2> *A_src = &A_cur;
    Buffer<num_t, 2> *A_dst = &A_next;

    for (int t = 0; t < tsteps; t++) {
        // Bind the current state as the input image for this step
        A_prev_param.set(*A_src);

        // Realize only the interior region [1 .. n-2] x [1 .. n-2].
        // This keeps all stencil accesses in-bounds without explicit
        // boundary conditions, since neighbors of interior points are
        // always in [0 .. n-1].
        //
        // Halide's bounds inference will deduce that A_prev_param must
        // be valid in [0 .. n-1]^2, which is true for A_src. No
        // extra padding or boundary Func is required.
        Buffer<num_t> interior =
            A_dst->cropped(0, 1, n - 2) // crop x from 1, extent n-2 -> [1..n-2]
                 .cropped(1, 1, n - 2); // crop y from 1, extent n-2 -> [1..n-2]

        seidel_step.realize(interior);

        // Copy boundary values (edges) unchanged from the previous state.
        // In the original C code, boundaries are never updated (loops start at 1
        // and end at n-2), so they remain constant across time steps.
        //
        // This is O(n) work per time step vs O(n^2) for the stencil, so the
        // cost is negligible compared to the interior compute.
        // Top and bottom rows
        for (int j = 0; j < n; j++) {
            (*A_dst)(j, 0)     = (*A_src)(j, 0);
            (*A_dst)(j, n - 1) = (*A_src)(j, n - 1);
        }
        // Left and right columns (excluding corners which are already set)
        for (int i = 1; i < n - 1; i++) {
            (*A_dst)(0,     i) = (*A_src)(0,     i);
            (*A_dst)(n - 1, i) = (*A_src)(n - 1, i);
        }

        // Swap the role of the buffers for the next iteration
        Buffer<num_t, 2> *tmp = A_src;
        A_src = A_dst;
        A_dst = tmp;
    }

    // After the loop, A_src points to the buffer with the final data
    Buffer<num_t, 2> &A_final = *A_src;

    // Stop timing
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result to stderr (similar to the gemm example)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Recall: A[i][j] in C is A_final(j, i) in Halide.
                std::cerr << A_final(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds with 6 decimal places
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
